INSERT INTO `promotions` (`id`, `title`, `category`, `image_path`, `description`, `bonus_amount`, `start_date`, `end_date`, `is_new`, `status`, `created_at`, `wager_multiplier`, `target_group`, `bonus_percent`, `subtitle`) VALUES
(3, 'বন্ধুদের আমন্ত্রণ করুন আজীবন সুবিধা', 'all', 'assets/img/promos/promo3.jpg', 'প্রতি মাসে আয় করুন ১,৮৮৮,০০০ টাকা। ১,৮৮৮,০০০ উপার্জনের উপায়।', '5% Bonus', '2026-01-01', '2026-12-31', 0, 'active', '2026-01-08 22:00:21', 10, 'all', 5, NULL),
(4, 'প্রথম ডিপোজিট বোনাস ১২৯%', 'deposit', 'assets/img/promos/promo1.jpg', 'আপনার প্রথম ডিপোজিটে পান বিশাল ১২৯% বোনাস। এখনই ডিপোজিট করুন এবং খেলা শুরু করুন!', '129% Bonus', '2026-01-01', '2030-12-31', 1, 'active', '2026-01-20 22:58:27', 129, 'all', 129, NULL),
(5, 'এজেন্ট ৪ সুপার কমিশন', '', 'assets/img/promos/promo4.jpg', 'বন্ধুদের আমন্ত্রণ জানান এবং আজীবন ৪টি সুপার কমিশন উপভোগ করুন। প্রতিটি রেফারেল এ ৩০০ টাকা এবং ৩ স্তরের কমিশন।', '15% Bonus', '2026-01-01', '2030-12-31', 1, 'active', '2026-01-20 22:58:27', 15, 'all', 15, NULL),
